/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountStoreLocator, type StoreLocatorOptions } from "../../components/store-locator/StoreLocatorEngine.js";
import type { MotionController } from "../../components/store-locator/motion-runtime";

export function StoreLocator({ options, className }: { options?: StoreLocatorOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountStoreLocator(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="store-locator" />;
}

